@php($c='min-h-11 w-full rounded-xl border px-3.5 py-2.5')<x-admin.layout :title="$redirect->exists?'Edit redirect':'Add redirect'" eyebrow="SEO"><form method="POST" action="{{ $redirect->exists?route('admin.redirects.update',$redirect):route('admin.redirects.store') }}" class="mx-auto max-w-2xl space-y-5 rounded-2xl bg-white p-5 ring-1 ring-slate-200">@csrf @if($redirect->exists)@method('PUT')@endif<x-admin.form-field name="source_path" label="Old path" hint="Internal path beginning with /." required><input name="source_path" value="{{ old('source_path',$redirect->source_path) }}" placeholder="/old-page" class="{{ $c }}"></x-admin.form-field><x-admin.form-field name="destination_path" label="Destination path" required><input name="destination_path" value="{{ old('destination_path',$redirect->destination_path) }}" placeholder="/new-page" class="{{ $c }}"></x-admin.form-field><div class="grid gap-4 sm:grid-cols-2"><select name="status_code" class="{{ $c }}">@foreach([301,302,307,308] as $code)<option value="{{ $code }}" @selected(old('status_code',$redirect->status_code??301)==$code)>{{ $code }}</option>@endforeach</select><label class="flex min-h-11 items-center gap-3"><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$redirect->is_active??true))> Active</label></div><button class="min-h-12 w-full rounded-xl bg-[#082f57] text-white">Save redirect</button></form></x-admin.layout>
